#!/usr/bin/env bun
// Taskboard CLI - dependency-free TypeScript task manager for Bun

import { existsSync, renameSync, writeFileSync, readFileSync, unlinkSync } from "fs";
import { join, dirname } from "path";
import { tmpdir } from "os";

// ---------- Types ----------
interface Task {
  id: number;
  title: string;
  status: "open" | "done";
  tags: string[];
  createdAt: string;
  due?: string;
  completedAt?: string;
}

interface DB {
  nextId: number;
  tasks: Task[];
}

// ---------- Helpers ----------

function dbPath(): string {
  return process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");
}

function fail(msg: string): never {
  process.stderr.write("error: " + msg + "\n");
  process.exit(1);
}

function loadDB(): DB {
  const p = dbPath();
  if (!existsSync(p)) {
    return { nextId: 1, tasks: [] };
  }
  let raw: string;
  try {
    raw = readFileSync(p, "utf-8");
  } catch (e) {
    fail("cannot read database file");
  }
  let data: any;
  try {
    data = JSON.parse(raw!);
  } catch {
    fail("malformed database");
  }
  if (
    typeof data !== "object" ||
    data === null ||
    typeof data.nextId !== "number" ||
    !Array.isArray(data.tasks)
  ) {
    fail("malformed database");
  }
  return data as DB;
}

function saveDB(db: DB): void {
  const p = dbPath();
  const dir = dirname(p);
  const tmp = join(dir, `.taskboard.tmp.${process.pid}.${Date.now()}.json`);
  writeFileSync(tmp, JSON.stringify(db, null, 2));
  renameSync(tmp, p);
}

function isValidDate(s: string): boolean {
  const re = /^(\d{4})-(\d{2})-(\d{2})$/;
  const m = re.exec(s);
  if (!m) return false;
  const y = parseInt(m[1], 10);
  const mo = parseInt(m[2], 10);
  const d = parseInt(m[3], 10);
  const dt = new Date(y, mo - 1, d);
  return (
    dt.getFullYear() === y &&
    dt.getMonth() === mo - 1 &&
    dt.getDate() === d
  );
}

function todayLocal(): string {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, "0");
  const d = String(now.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function isoNow(): string {
  return new Date().toISOString();
}

function normalizeTags(raw: string | undefined): string[] {
  if (!raw) return [];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const t of raw.split(",")) {
    const tag = t.trim().toLowerCase();
    if (tag && !seen.has(tag)) {
      seen.add(tag);
      out.push(tag);
    }
  }
  return out;
}

// ---------- Argument parsing ----------

interface ParsedArgs {
  positional: string[];
  flags: Record<string, string | boolean>;
}

function parseArgs(argv: string[]): ParsedArgs {
  const positional: string[] = [];
  const flags: Record<string, string | boolean> = {};
  const knownFlags = new Set(["title", "tags", "due", "status", "tag", "overdue"]);
  let i = 0;
  while (i < argv.length) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const name = a.slice(2);
      if (!knownFlags.has(name)) {
        fail(`unknown flag: --${name}`);
      }
      if (i + 1 < argv.length && !argv[i + 1].startsWith("--")) {
        flags[name] = argv[i + 1];
        i += 2;
      } else {
        flags[name] = true;
        i += 1;
      }
    } else {
      positional.push(a);
      i += 1;
    }
  }
  return { positional, flags };
}

function getFlagStr(flags: Record<string, string | boolean>, name: string): string | undefined {
  const v = flags[name];
  if (v === undefined) return undefined;
  if (v === true) return "";
  return v as string;
}

// ---------- Commands ----------

function cmdAdd(args: ParsedArgs): void {
  const title = getFlagStr(args.flags, "title");
  if (title === undefined) fail("add requires --title");
  if (title.trim() === "") fail("title must not be empty");
  const due = getFlagStr(args.flags, "due");
  if (due !== undefined && !isValidDate(due)) fail(`invalid due date: ${due}`);
  const tags = normalizeTags(getFlagStr(args.flags, "tags"));

  const db = loadDB();
  const task: Task = {
    id: db.nextId,
    title: title,
    status: "open",
    tags,
    createdAt: isoNow(),
  };
  if (due) task.due = due;
  db.tasks.push(task);
  db.nextId += 1;
  saveDB(db);
  console.log(JSON.stringify(task));
}

function cmdList(args: ParsedArgs): void {
  const statusFilter = getFlagStr(args.flags, "status");
  if (statusFilter !== undefined && statusFilter !== "open" && statusFilter !== "done") {
    fail(`invalid status filter: ${statusFilter}`);
  }
  const tagFilter = getFlagStr(args.flags, "tag");
  const overdueFilter = getFlagStr(args.flags, "overdue");
  if (overdueFilter !== undefined && !isValidDate(overdueFilter)) {
    fail(`invalid overdue date: ${overdueFilter}`);
  }

  const db = loadDB();
  let tasks = db.tasks.slice().sort((a, b) => a.id - b.id);
  if (statusFilter) {
    tasks = tasks.filter((t) => t.status === statusFilter);
  }
  if (tagFilter) {
    tasks = tasks.filter((t) => t.tags.includes(tagFilter.toLowerCase()));
  }
  if (overdueFilter) {
    tasks = tasks.filter(
      (t) => t.status === "open" && t.due !== undefined && t.due < overdueFilter
    );
  }
  console.log(JSON.stringify(tasks));
}

function cmdDone(args: ParsedArgs): void {
  if (args.positional.length < 1) fail("done requires an id");
  const id = parseInt(args.positional[0], 10);
  if (isNaN(id)) fail(`invalid id: ${args.positional[0]}`);
  const db = loadDB();
  const task = db.tasks.find((t) => t.id === id);
  if (!task) fail(`task ${id} not found`);
  if (task.status !== "done") {
    task.status = "done";
    task.completedAt = isoNow();
    saveDB(db);
  }
  console.log(JSON.stringify(task));
}

function cmdDelete(args: ParsedArgs): void {
  if (args.positional.length < 1) fail("delete requires an id");
  const id = parseInt(args.positional[0], 10);
  if (isNaN(id)) fail(`invalid id: ${args.positional[0]}`);
  const db = loadDB();
  const idx = db.tasks.findIndex((t) => t.id === id);
  if (idx === -1) fail(`task ${id} not found`);
  const [removed] = db.tasks.splice(idx, 1);
  saveDB(db);
  console.log(JSON.stringify(removed));
}

function cmdStats(): void {
  const db = loadDB();
  const today = todayLocal();
  const total = db.tasks.length;
  const open = db.tasks.filter((t) => t.status === "open").length;
  const done = db.tasks.filter((t) => t.status === "done").length;
  const overdue = db.tasks.filter(
    (t) => t.status === "open" && t.due !== undefined && t.due < today
  ).length;
  console.log(JSON.stringify({ total, open, done, overdue }));
}

// ---------- Main ----------

function main(): void {
  const argv = process.argv.slice(2);
  if (argv.length === 0) fail("no command given");
  const command = argv[0];
  const rest = argv.slice(1);
  const args = parseArgs(rest);
  switch (command) {
    case "add":
      cmdAdd(args);
      break;
    case "list":
      cmdList(args);
      break;
    case "done":
      cmdDone(args);
      break;
    case "delete":
      cmdDelete(args);
      break;
    case "stats":
      cmdStats();
      break;
    default:
      fail(`unknown command: ${command}`);
  }
}

main();

